import {initial,validate,createList,addTask,updateTask,STORAGE_KEY} from './model.js';
const $=id=>document.getElementById(id);let state,storageFailed=false;
try{const raw=localStorage.getItem(STORAGE_KEY);state=raw?validate(JSON.parse(raw)):initial();}catch{state=initial();storageFailed=true;}
let active=state.lists[0].id,mode=null;
const current=()=>state.lists.find(l=>l.id===active)||state.lists[0];
function notice(message){$('status').textContent=message;}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));return true;}catch{notice('Storage unavailable. Export a backup before closing this page.');return false;}}
function render(){
 $('lists').replaceChildren();for(const list of state.lists){const b=document.createElement('button');b.className=list.id===active?'active':'';b.setAttribute('aria-pressed',String(list.id===active));const dot=document.createElement('span');dot.className='dot '+(['lavender','sage','peach'].includes(list.color)?list.color:'lavender');const name=document.createElement('span');name.className='list-name';name.textContent=list.name;const count=document.createElement('span');count.className='number';count.textContent=list.tasks.filter(t=>!t.done).length;b.append(dot,name,count);b.onclick=()=>{active=list.id;notice('');render();};$('lists').append(b);}
 const list=current();$('title').textContent=list.name;const open=list.tasks.filter(t=>!t.done).length;$('subtitle').textContent='A soft landing for thoughts, plans, and little things.';$('count').textContent=`${open} open · ${list.tasks.length-open} completed`;
 const shown=list.tasks.filter(t=>$('show-done').checked||!t.done);$('tasks').replaceChildren();for(const task of shown){const row=document.createElement('div');row.className='task'+(task.done?' done':'');const check=document.createElement('input');check.type='checkbox';check.checked=task.done;check.setAttribute('aria-label',(task.done?'Reopen: ':'Complete: ')+task.text);check.onchange=()=>{updateTask(list,task.id,{done:check.checked});persist();render();notice(check.checked?'One less thing to carry. You can reopen it in Show completed.':'Thought reopened.');};const text=document.createElement('span');text.className='text';text.textContent=task.text;const edit=document.createElement('button');edit.className='edit';edit.textContent='Edit';edit.setAttribute('aria-label','Edit: '+task.text);edit.onclick=()=>openEditor('task',task);row.append(check,text,edit);$('tasks').append(row);}
 $('empty').hidden=shown.length>0;$('section-title').textContent=$('show-done').checked?'All thoughts':'Open thoughts';
}
function openEditor(type,task){mode={type,taskId:task?.id,listId:current().id};$('edit-title').textContent=type==='new'?'Make a little space':type==='rename'?'Rename your space':'Edit your thought';$('edit-label').textContent=type==='task'?'Thought':'Space name';$('edit-text').maxLength=type==='task'?2000:80;$('edit-text').value=type==='new'?'':type==='rename'?current().name:task.text;$('edit-error').textContent='';$('editor').showModal();$('edit-text').focus();}
$('capture').onsubmit=e=>{e.preventDefault();try{addTask(current(),$('thought').value);const saved=persist();$('thought').value='';render();if(saved)notice('Saved in this browser.');$('thought').focus();}catch(error){notice(error.message);}};
$('new-list').onclick=()=>openEditor('new');$('rename').onclick=()=>openEditor('rename');$('cancel').onclick=()=>$('editor').close();$('show-done').onchange=render;
$('edit-form').onsubmit=e=>{e.preventDefault();try{const value=$('edit-text').value.trim();if(!value)throw Error('Add some text first.');if(mode.type==='new')active=createList(state,value,['lavender','sage','peach'][state.lists.length%3]).id;else{const list=state.lists.find(l=>l.id===mode.listId);if(mode.type==='rename'){if(value.length>80)throw Error('Keep the name under 80 characters.');list.name=value;}else updateTask(list,mode.taskId,{text:value});}persist();$('editor').close();render();}catch(error){$('edit-error').textContent=error.message;}};
$('export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='quiet-list-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Backup downloaded. Keep it somewhere safe.');};
$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{if(file.size>5000000)throw Error('Choose a backup smaller than 5 MB.');const incoming=validate(JSON.parse(await file.text()));if(!confirm('Replace the lists in this browser with this backup? Export your current lists first if you want to keep them.'))return;state=incoming;active=state.lists[0].id;const saved=persist();render();if(saved)notice('Backup restored.');}catch(error){notice(error.message||'Could not read this backup.');}finally{$('file').value='';}};
render();if(storageFailed)notice('Existing storage could not be read. No old data was overwritten. Export any new work before closing.');
